import{Engine,esc}from'./base.js';export const inDecade=(year,start)=>year>=start&&year<start+10;
export default class Timeline extends Engine{constructor(h,c){super(h,c);this.events=c.chapter.timeline;this.selected=0;this.zoom=1;this.focusDecade=null;this.seen=new Set;const first=Math.floor(Math.min(...this.events.map(e=>e.year))/10)*10,last=Math.floor(Math.max(...this.events.map(e=>e.year))/10)*10,decades=Array.from({length:Math.round((last-first)/10)+1},(_,i)=>first+i*10);h.innerHTML=`<div class="engineTools"><label>${c.label('Timeline scale','समयरेखा पैमाना')} <select id="timelineScale"><option value="1">${c.dual('Full period','पूरा काल')}</option><option value="2">${c.dual('Decade focus','दशक पर ध्यान')}</option><option value="4">${c.dual('Close view','नज़दीक दृश्य')}</option></select></label><label>${c.label('Decade','दशक')}<select id="decade">${decades.map(y=>`<option>${y}</option>`).join('')}</select></label></div><div class="timelineTrack" tabindex="0" aria-label="${c.dual('Drag to scroll timeline; arrow keys move events','खींचकर समयरेखा चलाएँ; तीर कुंजियों से घटना चुनें')}"><div class="timelineRail"></div></div><p class="timelineModel">${c.dual('Cards follow chronological order; their spacing is not proportional to elapsed time. Decade focus filters the events.','कार्ड कालक्रम में हैं; दूरी बीते समय के अनुपात में नहीं है। दशक चुनने पर उसी दशक की घटनाएँ दिखती हैं।')}</p><article class="eventDetail" aria-live="polite"></article>`;this.track=h.querySelector('.timelineTrack');this.rail=h.querySelector('.timelineRail');this.detail=h.querySelector('.eventDetail');this.on(h.querySelector('#timelineScale'),'change',e=>{this.zoom=+e.target.value;this.focusDecade=this.zoom>1?+h.querySelector('#decade').value:null;this.metrics.zoom=this.zoom;this.render();let ids=this.visibleIndices();this.show(ids.includes(this.selected)?this.selected:ids[0])});this.on(h.querySelector('#decade'),'change',e=>{let year=+e.target.value;this.focusDecade=year;this.zoom=Math.max(2,this.zoom);h.querySelector('#timelineScale').value=this.zoom;this.metrics.zoom=this.zoom;this.render();this.show(this.visibleIndices()[0],true)});let drag=null;this.on(this.track,'pointerdown',e=>{drag=[e.clientX,this.track.scrollLeft];this.moved=false;if(e.pointerType!=='mouse')return});this.on(this.track,'pointermove',e=>{if(!drag)return;let dx=e.clientX-drag[0];if(Math.abs(dx)>6){this.moved=true;this.track.setPointerCapture(e.pointerId)}this.track.scrollLeft=drag[1]-dx});this.on(this.track,'pointerup',()=>{drag=null});this.on(this.track,'pointercancel',()=>drag=null);this.on(this.track,'keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();let ids=this.visibleIndices(),i=ids.indexOf(this.selected);this.show(ids[Math.max(0,Math.min(ids.length-1,i+(e.key==='ArrowRight'?1:-1)))],true)}});this.on(this.rail,'click',e=>{let b=e.target.closest('[data-event]');if(b&&!this.moved)this.show(+b.dataset.event)});this.render();this.show(0)}visibleIndices(){return this.events.map((e,i)=>i).filter(i=>this.zoom===1||this.focusDecade===null||inDecade(this.events[i].year,this.focusDecade))}render(){let c=this.ctx,min=this.events[0].year,max=this.events.at(-1).year;let ids=this.visibleIndices(),pitch=this.zoom===1?225:this.zoom===2?265:315;this.rail.style.width=Math.max(700,ids.length*pitch+30)+'px';this.rail.innerHTML=ids.map((i,j)=>{let e=this.events[i];return`<button class="eventCard ${i===this.selected?'selected':''}" style="width:${pitch-15}px;left:${20+j*pitch}px;top:${i%2?180:20}px" data-event="${i}" aria-expanded="${i===this.selected}"><span class="eventDate">${esc(e.date)}</span>${this.labels?c.H(e.title,3):''}</button>`}).join('');if(!ids.length)this.rail.innerHTML=`<p>${c.dual('No listed events in this decade. Choose another decade or Full period.','इस दशक में सूचीबद्ध घटना नहीं है। दूसरा दशक या पूरा काल चुनें।')}</p>`}show(i,scroll=false){if(i===undefined){this.detail.innerHTML='';return}this.selected=i;this.seen.add(i);let e=this.events[i],c=this.ctx;this.detail.innerHTML=c.H(e.title,3)+`<p class="eyebrow">${esc(e.date)}</p><dl><dt>${c.label('Cause','कारण')}</dt><dd>${esc(c.text(e.cause))}</dd><dt>${c.label('Effect','प्रभाव')}</dt><dd>${esc(c.text(e.effect))}</dd><dt>${c.label('Key people','प्रमुख लोग')}</dt><dd>${esc(c.text(e.people))}</dd></dl>`;for(let b of this.rail.querySelectorAll('button')){let on=+b.dataset.event===i;b.classList.toggle('selected',on);b.setAttribute('aria-expanded',String(on));if(on&&scroll)b.scrollIntoView({block:'nearest',inline:'center',behavior:'auto'})}this.metrics.visited=this.seen.size;this.emit(`${e.date}: ${c.text(e.title)} — ${c.text(e.effect)}`)}run(){this.schedule(()=>{let ids=this.visibleIndices();if(ids.length)this.show(ids[(ids.indexOf(this.selected)+1)%ids.length],true);this.run()},4200)}resetView(){this.zoom=1;this.focusDecade=null;this.host.querySelector('#timelineScale').value='1';this.render();this.track.scrollLeft=0}}
